CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 ANY, c1 REAL UNIQUE, c2 REAL DEFAULT 'd', c3 INTEGER COLLATE NOCASE) STRICT;
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES(4.5e-310, 29.776, 34.375, 158);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES(-1e308, 21.672, 0.477, 1e308);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INTEGER CHECK(c0 IS NULL OR length(c0) < 40), c1 TEXT, c2 INTEGER, c3 REAL, c4 INTEGER UNIQUE, ref INTEGER REFERENCES t0(id)) STRICT;
SELECT length('x_y'), upper('x_y'), lower('x_y'), substr('x_y', 1, 3), instr('x_y', 'xi'), replace('x_y', '', ''), trim('x_y'), ltrim('x_y', 'ab'), hex('x_y'), quote('x_y'), unicode('x_y'), 'x_y' LIKE 'A%', 'x_y' GLOB 'a*', char(89, 873), 'x_y' || 'xi', 'x_y' < 'xi', 'x_y' = 'xi' COLLATE NOCASE;
SELECT length('naïve'), upper('naïve'), lower('naïve'), substr('naïve', 4, 1), instr('naïve', 'Ελλάδα'), replace('naïve', 'a', 'XY'), trim('naïve'), ltrim('naïve', 'ab'), hex('naïve'), quote('naïve'), unicode('naïve'), 'naïve' LIKE '%é%', 'naïve' GLOB '?', char(72, 465), 'naïve' || 'Ελλάδα', 'naïve' < 'Ελλάδα', 'naïve' = 'Ελλάδα' COLLATE NOCASE;
SELECT length(''), upper(''), lower(''), substr('', 1, 0), instr('', 'MU'), replace('', 'e', ''), trim(''), ltrim('', 'ab'), hex(''), quote(''), unicode(''), '' LIKE '%é%', '' GLOB '*', char(66, 586), '' || 'MU', '' < 'MU', '' = 'MU' COLLATE NOCASE;
SELECT length('omicron'), upper('omicron'), lower('omicron'), substr('omicron', -2, 1), instr('omicron', 'epsilon'), replace('omicron', '', '_'), trim('omicron'), ltrim('omicron', 'ab'), hex('omicron'), quote('omicron'), unicode('omicron'), 'omicron' LIKE 'A%', 'omicron' GLOB '*', char(73, 732), 'omicron' || 'epsilon', 'omicron' < 'epsilon', 'omicron' = 'epsilon' COLLATE NOCASE;
UPDATE t0 SET c0 = c0 WHERE iif(-(c1), 'señor', 'NULL');
DELETE FROM t0 WHERE id % 5 = 1;
SELECT * FROM t0 ORDER BY id, c0 DESC, c1, c2 DESC, c3;
